window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-7001\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφοίβαντος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7001 na letra α · nº geral 7001</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">não purificado; maculado. 〈ἀ-, φοι­βαίνω〉</p></section></article>\n<article id=\"entry-dgp-7002\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφομοιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7002 na letra α · nº geral 7002</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar semelhante; assemelhar algo ou alguém, ac., a, dat. 2 reproduzir; copiar 3 assimilar; comparar uma coisa, ac., a outra, dat. ♦ pas. 4 tornar-se semelhante a, dat. ou πρός e ac. 〈ἀπό, ὁμοῖος〉</p></section></article>\n<article id=\"entry-dgp-7003\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφομοίωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7003 na letra α · nº geral 7003</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">assimilação; semelhança. 〈ἀπό, ὁμοῖος〉</p></section></article>\n<article id=\"entry-dgp-7004\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφοπλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 7004 na letra α · nº geral 7004</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἀφώπλισα) 1 desarmar; despojar alguém, ac., de algo, gen. ♦ méd. 2 desarmar-se: ἀφοπλίζομαι ἔντεα hom. depor as armas; retirar a armadura. 〈ἀπό, ὁπλίζω〉</p></section></article>\n<article id=\"entry-dgp-7005\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφοράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7005 na letra α · nº geral 7005</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἀφεώρων, fut. ἀπόψομαι, aor.2 ἀπεῖδον, perf. ἀφεώρακα) 1 olhar de longe; avistar 2 fixar o olhar em; contemplar algo, ac. ou πρός, εἰς ou ἐπί e ac. 3 intr. olhar para outro lado ♦ méd. 4 avistar 5 observar de longe. 〈ἀπό, ὁράω〉</p></section></article>\n<article id=\"entry-dgp-7006\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφόρητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7006 na letra α · nº geral 7006</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 insuportável 2 que ainda não foi usado; novo. 〈ἀ-, φορέω〉</p></section></article>\n<article id=\"entry-dgp-7007\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7007 na letra α · nº geral 7007</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ausência de produção; incapacidade para produzir; esterilidade. 〈ἄφορος〉</p></section></article>\n<article id=\"entry-dgp-7008\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφορίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 7008 na letra α · nº geral 7008</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀφοριῶ, aor. ἀφώρισα; pas. aor. ἀφωρίσθην, perf. ἀφώρισμαι) 1 fixar os limites; demarcar; circunscrever 2 encerrar; terminar; finalizar (obra) 3 separar; distinguir; pôr à parte; escolher 4 excluir; expulsar; banir 5 bíbl. excomungar ♦ méd. 6 delimitar para si; apropriar-se de, ac. 7 dar uma definição; definir 8 terminar 9 afastar de si; esquivar-se de, ac. 〈ἀπό, ὁρίζω〉</p></section></article>\n<article id=\"entry-dgp-7009\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφορμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7009 na letra α · nº geral 7009</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀφορμήσω) 1 lançar-se em, ac. 2 afastar-se; partir de, gen. ou ἐκ e gen. 3 irromper; jorrar 4 re­ter o impulso; conter-se; sentir aversão ♦ méd. 5 lançar-se; afastar-se; partir. 〈ἀπό, ὁρμάω〉</p></section></article>\n<article id=\"entry-dgp-7010\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφορμή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7010 na letra α · nº geral 7010</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ponto de partida; local de partida; base de operações militares 2 ponto de partida; origem (de doença) 3 causa; pretexto; ocasião: ἀφορμὴν ἔχειν πρός ou ἔς τι ter ocasião ou pretexto para alguma coisa 4 meio para empreender, recursos; capital: ἔργων ἀφορμή xen. recursos para pagar os trabalhos 5 repugnância; aversão. 〈ἀπό, ὁρμή〉</p></section></article>\n<article id=\"entry-dgp-7011\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφορμίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 7011 na letra α · nº geral 7011</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só subj aor.2 2ª sing. ἀφορμίσῃ) fazer sair do porto (navio).</p></section></article>\n<article id=\"entry-dgp-7012\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφόρμικτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7012 na letra α · nº geral 7012</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">não acompanhado de φόρμιγξ, espécie de lira. 〈ἀ-, φορμίζω〉</p></section></article>\n<article id=\"entry-dgp-7013\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄφορμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7013 na letra α · nº geral 7013</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se afasta de; que parte de, gen. 〈ἀπό, ὁρμή〉</p></section></article>\n<article id=\"entry-dgp-7014\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄφορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7014 na letra α · nº geral 7014</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que não produz; estéril; infecundo 2 que torna improdutivo ou estéril 3 que não paga imposto. 〈ἀ-, φέρω〉</p></section></article>\n<article id=\"entry-dgp-7015\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφοσιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7015 na letra α · nº geral 7015</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀφοσιώσω) 1 purificar; consagrar algo, ac., a alguém, dat. ♦ méd. 2 purificar-se; oferecer um sacrifício expiatório; cumprir os deveres religiosos 3 afastar com expiação (desgraças). 〈ἀπό, ὁσιόω〉</p></section></article>\n<article id=\"entry-dgp-7016\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφοσίωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7016 na letra α · nº geral 7016</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cumprimento de ritual de purificação 2 purificação; expiação 3 cumprimento formal de um dever. 〈ἀφοσιόω〉</p></section></article>\n<article id=\"entry-dgp-7017\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφοῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 7017 na letra α · nº geral 7017</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">imper. aor. méd. de ἀφίημι.</p></section></article>\n<article id=\"entry-dgp-7018\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁφόων</h1><div class=\"entry-meta\"><span>DGP · ordem 7018 na letra α · nº geral 7018</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. ép. de ἁφάω.</p></section></article>\n<article id=\"entry-dgp-7019\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφραδέω</h1><div class=\"entry-meta\"><span>DGP · ordem 7019 na letra α · nº geral 7019</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) ser insensato. 〈ἀφραδής〉</p></section></article>\n<article id=\"entry-dgp-7020\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφραδέως</h1><div class=\"entry-meta\"><span>DGP · ordem 7020 na letra α · nº geral 7020</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo insensato; insensatamente.</p></section></article>\n<article id=\"entry-dgp-7021\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφραδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 7021 na letra α · nº geral 7021</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">insensato; louco; insensível. 〈ἀ-, φράζομαι〉</p></section></article>\n<article id=\"entry-dgp-7022\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφραδίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7022 na letra α · nº geral 7022</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 insensatez; irreflexão; loucura 2 inexperiência. 〈ἀφραδής〉</p></section></article>\n<article id=\"entry-dgp-7023\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 7023 na letra α · nº geral 7023</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser insensato. 〈ἄφρων〉</p></section></article>\n<article id=\"entry-dgp-7024\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄφρακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7024 na letra α · nº geral 7024</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem muralhas em volta; não protegido; desguarnecido 2 indefeso; sem defesa; desarmado. 〈ἀ-, φράσσω〉</p></section></article>\n<article id=\"entry-dgp-7025\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφράσμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7025 na letra α · nº geral 7025</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος insensato.</p></section></article>\n<article id=\"entry-dgp-7026\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄφραστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7026 na letra α · nº geral 7026</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 indizível; inexprimível 2 admirável; estranho; maravilhoso 3 imperceptível; invisível; incompreensível 4 imprevisível; inesperado; imprevisto 5 oculto; secreto 6 irracional; insensato. 〈ἀ-, φράζομαι〉</p></section></article>\n<article id=\"entry-dgp-7027\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφράστως</h1><div class=\"entry-meta\"><span>DGP · ordem 7027 na letra α · nº geral 7027</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sem reflexão; de improviso.</p></section></article>\n<article id=\"entry-dgp-7028\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7028 na letra α · nº geral 7028</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) espumar; estar coberto ou cobri-se de espuma. 〈ἀφρός〉</p></section></article>\n<article id=\"entry-dgp-7029\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφρήτωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 7029 na letra α · nº geral 7029</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) sem família; sem laço familiar ou social. 〈ἀ- φράτωρ〉</p></section></article>\n<article id=\"entry-dgp-7030\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 7030 na letra α · nº geral 7030</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀφρίσω) = ἀφρέω.</p></section></article>\n<article id=\"entry-dgp-7031\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφροδισιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 7031 na letra α · nº geral 7031</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀφροδισιάσω) 1 (homem) ter relações sexuais ♦ pas. 2 (mulher) ter relações sexuais. 〈ἀφρο­δίσιος〉</p></section></article>\n<article id=\"entry-dgp-7032\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφροδίσιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 7032 na letra α · nº geral 7032</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 de Afrodite; referente a Afrodite ♦ ὁ Ἀφροδίσιος 2 Afrodísio, n. de um mês em Chipre ♦ τὸ ἀφροδίσιον 3 templo ou estátua de Afrodite ♦ τὰ ἀφροδίσια 4 prazeres do amor 5 festa de Afrodite 6 rar. órgãos sexuais. 〈Ἀφροδίτη〉</p></section></article>\n<article id=\"entry-dgp-7033\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀφροδίτη</h1><div class=\"entry-meta\"><span>DGP · ordem 7033 na letra α · nº geral 7033</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Ἁφροδίτη, ης (ἡ) 1 Afrodite, deusa do amor e da beleza, que os gregos acreditavam que tivesse nascido da espuma das ondas (ἐκ τοῦ ἀφροῦ) 2 prazer amoroso 3 desejo violento; paixão 4 beleza; graça; encanto 5 Afrodite, símbolo de amizade, da sorte 6 Afrodite ou Vênus, planeta 7 tempo de semeadura.</p></section></article>\n<article id=\"entry-dgp-7034\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφρονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7034 na letra α · nº geral 7034</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser insensato; estar louco 2 tornar insensato. 〈ἄφρων〉</p></section></article>\n<article id=\"entry-dgp-7035\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄφροντις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 7035 na letra α · nº geral 7035</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) descuidado; despreocupado de, gen. 〈ἀ-, φροντίς〉</p></section></article>\n<article id=\"entry-dgp-7036\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφρόντιστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7036 na letra α · nº geral 7036</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 despreocupado; tranqüilo 2 descuidado; irrefletido; cego 3 rar. que não causa preocupação 4 que não foi levado em conta; inesperado. 〈ἀ-, φροντίζω〉</p></section></article>\n<article id=\"entry-dgp-7037\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφροντίστως</h1><div class=\"entry-meta\"><span>DGP · ordem 7037 na letra α · nº geral 7037</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. irrefletidamente; inconsideradamente; despreocupadamente; ἀ. ἔχειν não ter preocupação.</p></section></article>\n<article id=\"entry-dgp-7038\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφρόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 7038 na letra α · nº geral 7038</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. desarrazoadamente; loucamente. 〈ἄφρων〉</p></section></article>\n<article id=\"entry-dgp-7039\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφρός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7039 na letra α · nº geral 7039</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espuma 2 baba 3 sardinha.</p></section></article>\n<article id=\"entry-dgp-7040\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφροσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7040 na letra α · nº geral 7040</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falta de senso; demência; loucura 2 pl. atos de loucura; loucuras; tolices. 〈ἄφρων〉</p></section></article>\n<article id=\"entry-dgp-7041\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφρούρητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7041 na letra α · nº geral 7041</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">não vigiado; sem guarnição. 〈ἀ-, ἀφρουρά〉</p></section></article>\n<article id=\"entry-dgp-7042\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφρώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 7042 na letra α · nº geral 7042</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espumoso; espumante. 〈ἀφρός〉</p></section></article>\n<article id=\"entry-dgp-7043\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7043 na letra α · nº geral 7043</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 privado de sentimento; sem vida 2 que não é senhor de seus sentimentos; demente; louco. 〈ἀ-, φρήν〉</p></section></article>\n<article id=\"entry-dgp-7044\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυβρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 7044 na letra α · nº geral 7044</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀφυβρίσω, át. ἀφυβριῶ, aor. ἀφύβρισα, perf. ἀφύβρικα) 1 desenfrear-se; exceder-se 2 entregar-se sem medida a algo, εἰς e ac. 3 acalmar-se 4 (vinho) perder a força. 〈ἀπό, ὑβρίζω〉</p></section></article>\n<article id=\"entry-dgp-7045\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφύη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7045 na letra α · nº geral 7045</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">peixe pequeno; anchova; sardinha.</p></section></article>\n<article id=\"entry-dgp-7046\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 7046 na letra α · nº geral 7046</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que não cresceu normalmente; pequeno; mal formado 2 mal dotado; inábil; impróprio para, πρός e ac. 3 (coisa) não feito para; não adequado para; desfavorável a algo, dat. 〈ἀ-, φύομαι〉</p></section></article>\n<article id=\"entry-dgp-7047\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυΐα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7047 na letra α · nº geral 7047</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">incapacidade natural; inaptidão para algo, gen. ou πρός e ac. 〈ἀ-, φύομαι〉</p></section></article>\n<article id=\"entry-dgp-7048\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄφυκτος ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7048 na letra α · nº geral 7048</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de que não se pode fugir; inevitável; infalível 2 sem escapatória; sem réplica; embaraçoso 3 que não pode fugir. 〈ἀ-, φεύγω〉</p></section></article>\n<article id=\"entry-dgp-7049\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυλακτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7049 na letra α · nº geral 7049</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀφυλακτήσω) não se pôr em guarda; não se precaver; ser negligente com, gen. 〈ἀφύλακτος〉</p></section></article>\n<article id=\"entry-dgp-7050\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφύλακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7050 na letra α · nº geral 7050</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que não toma cuidado com; que não se põe em guarda contra; incauto em relação a, πρός e ac. 2 com quem ou com que não se toma cuidado; não guardado; não protegido 3 de que não se pode escapar; inevitável. 〈ἀ-, φυλάσσω〉</p></section></article>\n<article id=\"entry-dgp-7051\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυλάκτως</h1><div class=\"entry-meta\"><span>DGP · ordem 7051 na letra α · nº geral 7051</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sem proteger-se; sem precaução.</p></section></article>\n<article id=\"entry-dgp-7052\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυλαξία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7052 na letra α · nº geral 7052</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">falta de vigilância; ausência de guardas; negligência. 〈ἀ-, φυλάσσω〉</p></section></article>\n<article id=\"entry-dgp-7053\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄφυλλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7053 na letra α · nº geral 7053</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que não tem folhas; desprovido de folhas; desfolhado 2 sem ramo (suplicante sem o ramo de oliveira) 3 que faz cair as folhas. 〈ἀ-, φύλλον〉</p></section></article>\n<article id=\"entry-dgp-7054\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυπνίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 7054 na letra α · nº geral 7054</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἀφύπνισα) 1 despertar do sono 2 intr. despertar; acordar ♦ méd. pas. 3 despertar; acordar. 〈ἀπό, ὑπνίζω〉</p></section></article>\n<article id=\"entry-dgp-7055\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυπνόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7055 na letra α · nº geral 7055</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 despertar; acordar 2 bíbl. adormecer ♦ méd. 3 adormecer. 〈ἀπό, ὑπνόω〉</p></section></article>\n<article id=\"entry-dgp-7056\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυσγετός1, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7056 na letra α · nº geral 7056</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lama.</p></section></article>\n<article id=\"entry-dgp-7057\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυσγετός2, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 7057 na letra α · nº geral 7057</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) grosso; espesso; abundante.</p></section></article>\n<article id=\"entry-dgp-7058\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυσσάμενος, ἀφύσσας</h1><div class=\"entry-meta\"><span>DGP · ordem 7058 na letra α · nº geral 7058</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. méd. poét. e part. aor. at. ép. de ἀφύσσω.</p></section></article>\n<article id=\"entry-dgp-7059\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφύσσατο, ἄφυσσε</h1><div class=\"entry-meta\"><span>DGP · ordem 7059 na letra α · nº geral 7059</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. méd. e aor. at. ép. de ἀφύσσω.</p></section></article>\n<article id=\"entry-dgp-7060\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυσσόμενος, ἄφυσσον</h1><div class=\"entry-meta\"><span>DGP · ordem 7060 na letra α · nº geral 7060</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. méd. poét. e imper. aor. ép. de ἀφύσσω.</p></section></article>\n<article id=\"entry-dgp-7061\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφύσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 7061 na letra α · nº geral 7061</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀφύσω, poét. ἀφύξω, aor. ἤφυσα, perf. desus.) 1 tirar para servir (líquido de recipiente); servir 2 penetrar; dilacerar 3 sondar; remexer ♦ méd. 4 servir-se (de bebida); acumular para si.</p></section></article>\n<article id=\"entry-dgp-7062\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυστερέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7062 na letra α · nº geral 7062</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 intr. ficar para trás; estar atrasado 2 reter; retardar. 〈ἀπό, ὑστερέω〉</p></section></article>\n<article id=\"entry-dgp-7063\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφυῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 7063 na letra α · nº geral 7063</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sem disposições naturais; com má disposição. 〈ἀφυής〉</p></section></article>\n<article id=\"entry-dgp-7064\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφῶ, ῇς, ῆ</h1><div class=\"entry-meta\"><span>DGP · ordem 7064 na letra α · nº geral 7064</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 de ἀφίημι.</p></section></article>\n<article id=\"entry-dgp-7065\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφώνητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7065 na letra α · nº geral 7065</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem voz; sem fala; mudo 2 inexprimível. 〈ἀ-, φωνέω〉</p></section></article>\n<article id=\"entry-dgp-7066\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄφωνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7066 na letra α · nº geral 7066</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem voz; incapaz de proferir um som; afônico 2 silencioso; mudo ♦ ἄφωνα adv. 3 sem fala ♦ τὰ ἄφωνα 4 Gram. consoantes. 〈ἀ-, φωνή〉</p></section></article>\n<article id=\"entry-dgp-7067\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφώνως</h1><div class=\"entry-meta\"><span>DGP · ordem 7067 na letra α · nº geral 7067</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sem falar. 〈ἀ-, φωνή〉</p></section></article>\n<article id=\"entry-dgp-7068\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀφωρισμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 7068 na letra α · nº geral 7068</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de modo separado; separadamente 2 de modo marcado; de modo preciso 3 em forma de aforisma. 〈ἀφορίζω〉</p></section></article>\n<article id=\"entry-dgp-7069\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀχαία1, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 7069 na letra α · nº geral 7069</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Ἀχαιά, ᾶς (ἡ) Aquéia, cognome de Deméter, na Ática.</p></section></article>\n<article id=\"entry-dgp-7070\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀχαΐα,</h1><div class=\"entry-meta\"><span>DGP · ordem 7070 na letra α · nº geral 7070</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. poét. Ἀχαιΐα, ας (ἡ) 1 Acaia, região do Pelo­poneso 2 Acaia, parte da Tessália, também chamada Ftiótida 3 Acaia, nome da Grécia como província romana sem a Macedônia. 〈Ἀχαιός〉</p></section></article>\n<article id=\"entry-dgp-7071\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀχαιΐη</h1><div class=\"entry-meta\"><span>DGP · ordem 7071 na letra α · nº geral 7071</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Ἀχαία1 e Ἀχαΐα2.</p></section></article>\n<article id=\"entry-dgp-7072\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχαιΐνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7072 na letra α · nº geral 7072</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gamo.</p></section></article>\n<article id=\"entry-dgp-7073\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀχαιΐς</h1><div class=\"entry-meta\"><span>DGP · ordem 7073 na letra α · nº geral 7073</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Ἀχαΐς.</p></section></article>\n<article id=\"entry-dgp-7074\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀχαικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 7074 na letra α · nº geral 7074</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Acaia; aqueu. 〈Ἀχαΐα〉</p></section></article>\n<article id=\"entry-dgp-7075\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀχαιός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 7075 na letra α · nº geral 7075</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aqueu ♦ ὁ Ἀχαιός 2 Aqueu, ancestral da raça dos aqueus.</p></section></article>\n<article id=\"entry-dgp-7076\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀχαΐς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 7076 na letra α · nº geral 7076</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 da Acaia; aquéia 2 da Grécia; grega ♦ ἡ Ἀχαΐς 3 mulher da Acaia; mulher grega 4 [γῆ] a Acaia ou a Tessália ou a Grécia.</p></section></article>\n<article id=\"entry-dgp-7077\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχαλίνωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7077 na letra α · nº geral 7077</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem freio; não enfreado; não re­freado 2 rebelde ao freio; indomável. 〈ἀ-, καλινόω〉</p></section></article>\n<article id=\"entry-dgp-7078\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχάλκευτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7078 na letra α · nº geral 7078</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">não forjado em bronze. 〈ἀ-, καλκεύω〉</p></section></article>\n<article id=\"entry-dgp-7079\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄχαλκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7079 na letra α · nº geral 7079</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem bronze 2 sem moeda de bronze; sem dinheiro. 〈ἀ-, χαλκός〉</p></section></article>\n<article id=\"entry-dgp-7080\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχάνεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7080 na letra α · nº geral 7080</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abertura escancarada; abismo; imensidão. 〈ἀχανή〉</p></section></article>\n<article id=\"entry-dgp-7081\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχάνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7081 na letra α · nº geral 7081</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acane, medida persa de secos 2 cesto; canastra.</p></section></article>\n<article id=\"entry-dgp-7082\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχανής1, ής ές</h1><div class=\"entry-meta\"><span>DGP · ordem 7082 na letra α · nº geral 7082</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que não abre a boca; de boca fechada; mudo. 〈ἀ-, χανεῖν〉</p></section></article>\n<article id=\"entry-dgp-7083\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχανής2, ής ές</h1><div class=\"entry-meta\"><span>DGP · ordem 7083 na letra α · nº geral 7083</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de boca aberta; boquiaberto 2 imenso; infinito. 〈ἀ- cop., χανεῖν〉</p></section></article>\n<article id=\"entry-dgp-7084\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχαράκωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7084 na letra α · nº geral 7084</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">não circundado de paliçada. 〈ἀ-, χαρακόω〉</p></section></article>\n<article id=\"entry-dgp-7085\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄχαρι</h1><div class=\"entry-meta\"><span>DGP · ordem 7085 na letra α · nº geral 7085</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">n. ou dat. jôn. de ἄχαρις.</p></section></article>\n<article id=\"entry-dgp-7086\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄχαρις, ις, ι</h1><div class=\"entry-meta\"><span>DGP · ordem 7086 na letra α · nº geral 7086</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ιτος, ac. ιν (comp. ἀχαρίστερος) 1 sem graça; sem atrativo 2 desagradável; incômodo; odioso 3 que não tem reconhecimento; ingrato 4 que não merece ser a causa de algo; indigno. 〈ἀ-, χάρις〉</p></section></article>\n<article id=\"entry-dgp-7087\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχαρίστερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7087 na letra α · nº geral 7087</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp. de ἄχαρις.</p></section></article>\n<article id=\"entry-dgp-7088\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχαριστέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 7088 na letra α · nº geral 7088</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀχαριστήσω) 1 não ter complacência com; ser descortês com; desagradar a, dat. 2 ser ingrato; não ter reconhecimento ♦ pas. 3 não alcançar gratidão; receber ingratidão. 〈ἀχάριστος〉</p></section></article>\n<article id=\"entry-dgp-7089\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχαριστία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7089 na letra α · nº geral 7089</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">falta de graça, de atrativo, de encanto; grosseria 2 falta de reconhecimento; ingratidão. 〈ἀχάριστος〉</p></section></article>\n<article id=\"entry-dgp-7090\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχάριστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7090 na letra α · nº geral 7090</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem graça; sem atrativo; desagradável 2 que não tem reconhecimento; ingrato com alguém, dat. ou πρός e ac. 3 mal recompensado. 〈ἀ-, χαρίζομαι〉</p></section></article>\n<article id=\"entry-dgp-7091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχαρίστως</h1><div class=\"entry-meta\"><span>DGP · ordem 7091 na letra α · nº geral 7091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de modo desagradável; sem benevolência; de má vontade 2 sem reconhecimento; de modo ingrato.</p></section></article>\n<article id=\"entry-dgp-7092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχάριτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7092 na letra α · nº geral 7092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desagradável; penoso; enfadonho 2 sem reconhecimento; ingrato 3 que não obtém retribuição; que não inspira gratidão. 〈ἀ-, χάρις〉</p></section></article>\n<article id=\"entry-dgp-7093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀχαρναί, ῶν (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7093 na letra α · nº geral 7093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Acarnas, demo ático.</p></section></article>\n<article id=\"entry-dgp-7094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄχει1</h1><div class=\"entry-meta\"><span>DGP · ordem 7094 na letra α · nº geral 7094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. sing. de ἄχος.</p></section></article>\n<article id=\"entry-dgp-7095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄχει2</h1><div class=\"entry-meta\"><span>DGP · ordem 7095 na letra α · nº geral 7095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a. sing. impf. dór. de ἠχέω.</p></section></article>\n<article id=\"entry-dgp-7096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχείματος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7096 na letra α · nº geral 7096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">não abalado pelas tempestades; sem tempestades. 〈ἀ-, χεῖμα〉</p></section></article>\n<article id=\"entry-dgp-7097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄχειρ</h1><div class=\"entry-meta\"><span>DGP · ordem 7097 na letra α · nº geral 7097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ἄχειρος (masc., fem.) 1 sem mão 2 que não sabe usar as mãos; desajeitado. 〈ἀ-, χείρ〉</p></section></article>\n<article id=\"entry-dgp-7098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχείρητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7098 na letra α · nº geral 7098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">não manipulado; não plantado por mão mortal.</p></section></article>\n<article id=\"entry-dgp-7099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχειροποίητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7099 na letra α · nº geral 7099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. que não foi feito por mãos humanas. 〈ἀ-, χειροποιέομαι〉</p></section></article>\n<article id=\"entry-dgp-7100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀχείρωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 7100 na letra α · nº geral 7100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 não subjugado; não conquistado; indomável 2 não plantado pela mão do homem. 〈ἀ-, χειρόω〉</p></section></article>\n";
